struct Quat {
    double w{1.0};
    double x{0.0};
    double y{0.0};
    double z{0.0};

    Quat() = default;
    Quat(double w_, double x_, double y_, double z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat normalize() const {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n < 1e-12) return Quat(1.0, 0.0, 0.0, 0.0);
        return Quat(w / n, x / n, y / n, z / n);
